"""
Enchanting table, anvil and enchanted books (1.21.1 rules).

* Enchantment data comes from world/data/enchantments.json (generated by
  tools/gen_enchantment_data.py from the 1.21.1 registry): levels, costs,
  weights, the items each enchantment accepts, exclusive sets, treasure/curse.
* Enchantments live in the item's nbt: "enchantments" on tools and armour,
  "stored_enchantments" on enchanted books. Both map short names to levels.
* Enchanting table: the three offers come from the vanilla cost roll
  (EnchantmentMenu.slotsChanged / EnchantmentHelper.selectEnchantment), with
  the power from bookshelves around the table.
* Anvil: an enchanted book or a matching item merged into the left item, with
  the vanilla anvil cost (anvil_cost * level per enchantment).
"""

from __future__ import annotations

import json
import random
from functools import lru_cache
from pathlib import Path

DATA_FILE = Path(__file__).resolve().parent / "data" / "enchantments.json"
MAX_POWER = 15
TOO_EXPENSIVE = 40

# Item.getEnchantmentValue() for the common items (1.21.1)
_MATERIAL_ENCHANTABILITY = {"wooden": 15, "stone": 5, "iron": 14, "golden": 22, "diamond": 10,
                            "netherite": 15, "leather": 15, "chainmail": 12, "turtle": 9}
_TOOL_SUFFIXES = ("_sword", "_pickaxe", "_axe", "_shovel", "_hoe", "_helmet", "_chestplate",
                  "_leggings", "_boots")
_OTHER_ENCHANTABILITY = {"book": 1, "enchanted_book": 1, "bow": 1, "crossbow": 1, "fishing_rod": 1,
                         "trident": 1, "mace": 15}
BOOK_ITEMS = ("minecraft:book", "minecraft:enchanted_book")


@lru_cache(maxsize=1)
def _data():
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        entries = json.load(f)
    by_name = {}
    for entry in entries:
        entry["exclusive"] = set(entry["exclusive"])
        entry["supported"] = set(entry["supported"])
        by_name[entry["name"]] = entry
    return entries, by_name


def enchantments() -> list[dict]:
    return _data()[0]


def enchantment(name: str) -> dict | None:
    return _data()[1].get(short_name(name))


def short_name(name: str) -> str:
    return name.split(":", 1)[-1]


def protocol_id(name: str) -> int | None:
    """Registry id of an enchantment (the order of the synced enchantment registry)."""
    entry = enchantment(name)
    return None if entry is None else entry["id"]


def name_of_protocol_id(index: int) -> str | None:
    entries = enchantments()
    return entries[index]["name"] if 0 <= index < len(entries) else None


def item_enchantability(item_id: str) -> int:
    short = short_name(item_id)
    if short in _OTHER_ENCHANTABILITY:
        return _OTHER_ENCHANTABILITY[short]
    material, _, rest = short.partition("_")
    if material in _MATERIAL_ENCHANTABILITY and short.endswith(_TOOL_SUFFIXES):
        return _MATERIAL_ENCHANTABILITY[material]
    return 0


def is_book(item_id: str) -> bool:
    return item_id in BOOK_ITEMS


def accepts(item_id: str, name: str) -> bool:
    """Enchantment.canEnchant (books accept everything)."""
    entry = enchantment(name)
    if entry is None:
        return False
    if is_book(item_id):
        return True
    return short_name(item_id) in entry["supported"]


def compatible(name: str, existing) -> bool:
    """Not exclusive with any other enchantment already on the item."""
    entry = enchantment(name)
    short = short_name(name)
    for other in existing:
        other_short = short_name(other)
        if other_short == short:
            continue
        other_entry = enchantment(other)
        if other_entry is None:
            continue
        if other_short in entry["exclusive"] or short in other_entry["exclusive"]:
            return False
    return True


def level_cost(entry: dict, level: int, which: str) -> int:
    base, per_level = entry[which]
    return base + per_level * (level - 1)


@lru_cache(maxsize=1)
def bookshelf_states() -> frozenset:
    from .chunk_io import STATE_ID_TO_BLOCK
    return frozenset(sid for sid, (name, _) in STATE_ID_TO_BLOCK.items() if name == "minecraft:bookshelf")


def bookshelf_power(get_block, x: int, y: int, z: int) -> int:
    """EnchantmentMenu power: bookshelves in the ring around the table (each adds 1, max 15).

    A shelf counts when the block between it and the table is empty (air)."""
    shelves = bookshelf_states()
    power = 0
    for dx in range(-2, 3):
        for dz in range(-2, 3):
            if abs(dx) < 2 and abs(dz) < 2:
                continue            # the 3x3 around the table
            for dy in (0, 1):
                if get_block(x + dx, y + dy, z + dz) in shelves and \
                        get_block(x + dx // 2, y + dy, z + dz // 2) in (0, None):
                    power += 1
    return min(power, MAX_POWER)


def _weighted_pick(rng: random.Random, candidates: list[tuple[dict, int]]):
    total = sum(entry["weight"] for entry, _ in candidates)
    roll = rng.randrange(total)
    for entry, level in candidates:
        roll -= entry["weight"]
        if roll < 0:
            return entry, level
    return candidates[-1]


def select_enchantments(rng: random.Random, item_id: str, cost: int, allow_treasure: bool = False) -> list[tuple[str, int]]:
    """EnchantmentHelper.selectEnchantment: the enchantments one offer gives."""
    enchantability = item_enchantability(item_id) if not is_book(item_id) else 1
    if enchantability <= 0:
        return []
    cost += 1 + rng.randint(0, enchantability // 4) + rng.randint(0, enchantability // 4)
    factor = (rng.random() + rng.random() - 1.0) * 0.15
    cost = max(1, round(cost + cost * factor))

    def candidates_for(cost_value: int, chosen: list[tuple[dict, int]]):
        out = []
        for entry in enchantments():
            if entry["treasure"] and not allow_treasure:
                continue
            if not entry["in_enchanting_table"] or not accepts(item_id, entry["name"]):
                continue
            if any(entry["name"] == other["name"] or other["name"] in entry["exclusive"] or
                   entry["name"] in other["exclusive"] for other, _ in chosen):
                continue
            level = _fitting_level(entry, cost_value)
            if level:
                out.append((entry, level))
        return out

    candidates = candidates_for(cost, [])
    if not candidates:
        return []
    chosen: list[tuple[dict, int]] = [_weighted_pick(rng, candidates)]
    # EnchantmentHelper: each extra enchantment needs a roll under the (halving) cost
    while True:
        cost //= 2
        if rng.randint(0, 49) > cost:
            break
        more = candidates_for(cost, chosen)
        if not more:
            break
        chosen.append(_weighted_pick(rng, more))
    return [(entry["name"], level) for entry, level in chosen]


def _fitting_level(entry: dict, cost: int) -> int:
    """Highest level whose cost range contains ``cost`` (0 when none does)."""
    for level in range(entry["max_level"], 0, -1):
        if level_cost(entry, level, "min_cost") <= cost <= level_cost(entry, level, "max_cost"):
            return level
    return 0


def offer_costs(seed: int, item_id: str, power: int) -> list[int]:
    """EnchantmentMenu.slotsChanged: the three level costs for the current item and power."""
    enchantability = item_enchantability(item_id) if not is_book(item_id) else 1
    if enchantability <= 0:
        return [0, 0, 0]
    rng = random.Random(seed)
    costs = []
    for slot in range(3):
        cost = rng.randint(0, 7) + 1 + (power >> 1) + rng.randint(0, power)
        if slot == 0:
            cost = max(cost // 3, 1)
        elif slot == 1:
            cost = cost * 2 // 3 + 1
        else:
            cost = max(cost, power * 2)
        costs.append(cost if cost >= slot + 1 else 0)
    return costs


def enchanting_offers(seed: int, item_id: str, power: int) -> list[dict | None]:
    """The three offers: {"requirement": level needed, "levels": levels spent, "lapis": lapis spent,
    "enchants": [(name, level), ...]} or None."""
    costs = offer_costs(seed, item_id, power)
    offers = []
    for slot, cost in enumerate(costs):
        if cost <= 0:
            offers.append(None)
            continue
        enchants = select_enchantments(random.Random(seed + slot), item_id, cost)
        offers.append({"requirement": cost, "levels": slot + 1, "lapis": slot + 1, "enchants": enchants}
                      if enchants else None)
    return offers


def with_enchantments(item_id: str, nbt: dict, enchants: list[tuple[str, int]]) -> tuple[str, dict]:
    """Result of enchanting an item: books become enchanted books (stored_enchantments)."""
    nbt = dict(nbt or {})
    if is_book(item_id):
        stored = dict(nbt.get("stored_enchantments", {}))
        for name, level in enchants:
            stored[short_name(name)] = level
        nbt.pop("enchantments", None)
        nbt["stored_enchantments"] = stored
        return "minecraft:enchanted_book", nbt
    current = dict(nbt.get("enchantments", {}))
    for name, level in enchants:
        current[short_name(name)] = level
    nbt["enchantments"] = current
    return item_id, nbt


def anvil_merge(left, right):
    """The anvil result for (left item, right item): (result ItemStack or None, cost in levels)."""
    from .inventory import ItemStack
    if left is None or right is None or left.is_empty or right.is_empty:
        return None, 0
    source = dict(right.nbt.get("stored_enchantments", {}) if is_book(right.item_id)
                  else right.nbt.get("enchantments", {}))
    if is_book(right.item_id) and not source:
        return None, 0
    if not is_book(right.item_id) and right.item_id != left.item_id:
        return None, 0
    if not is_book(right.item_id) and not source:
        return None, 0
    if not (is_book(left.item_id) or item_enchantability(left.item_id) > 0):
        return None, 0

    current = dict(left.nbt.get("stored_enchantments", {}) if is_book(left.item_id)
                   else left.nbt.get("enchantments", {}))
    applied = []
    cost = 0
    for name, level in source.items():
        full = "minecraft:" + short_name(name)
        entry = enchantment(full)
        if entry is None or not accepts(left.item_id, full):
            continue
        if not compatible(full, list(current)):
            continue
        have = int(current.get(short_name(name), 0))
        if have > level:
            new_level = have
        elif have == level:
            new_level = min(level + 1, entry["max_level"])
        else:
            new_level = level
        if new_level == have:
            continue
        current[short_name(name)] = new_level
        applied.append((short_name(name), new_level))
        cost += entry["anvil_cost"] * new_level
    if not applied:
        return None, 0
    base_nbt = {k: v for k, v in left.nbt.items() if k not in ("enchantments", "stored_enchantments")}
    if is_book(left.item_id):
        result_id, nbt = "minecraft:enchanted_book", dict(base_nbt, stored_enchantments=current)
    else:
        result_id, nbt = left.item_id, dict(base_nbt, enchantments=current)
    result = ItemStack(result_id, 1, left.damage, nbt)
    return result, max(1, cost)
